// Package adapter is where an asset lands on one named harness.
//
// Most harnesses need no adapter at all. Of the harnesses surveyed for this
// design, 17 read `.agents/skills/<id>/SKILL.md` and 21 read `AGENTS.md`, so a
// skill and an instruction reach them through shared locations that no
// per-harness code computes. What has no shared equivalent anywhere is a rule, a
// command and a persona, and those reach a harness only through an adapter that
// knows its directories. Version 1 ships exactly one, `claude-code`, and "a
// harness with no adapter" is a supported state rather than a gap.
//
// This package is the contract and the registry; each adapter is its own package
// beneath it. The split is the extraction rule doing its work rather than a layer
// for its own sake: the install flow lives in the flat cli package and has to
// import the adapters, so an adapter importing a contract that lived beside the
// flow would be an import cycle one file later. Keeping the contract here is also
// what makes the import boundary checkable — an adapter may reach this package
// and general-purpose utilities, and nothing else.
//
// An adapter answers questions and performs no I/O of its own. It is handed a
// filesystem to detect through and it returns paths for the caller to write, for
// the same reason the harness roster holds no behaviour: two things that can each
// compute a destination eventually compute two different ones.
package adapter

import (
	"io/fs"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Adapter maps assets onto the files one harness reads.
//
// The contract is uniform on purpose: the install flow obtains a destination
// without knowing which harness it is addressing, so adding the second adapter
// is additive rather than another branch in the flow.
type Adapter interface {
	// Harness is the identity this adapter registers under, and the exact
	// string a manifest writes in `harnesses` or in an asset's `targets`.
	Harness() harness.ID

	// Detect reports whether the project already shows evidence of this
	// harness — its configuration directory existing, or a file only it
	// writes.
	//
	// The parameter is a filesystem rather than a directory path because
	// detection must create nothing: an fs.FS offers no way to write, so
	// "detection has no side effects" is a property of the signature rather
	// than a rule each adapter has to honour. A harness that is simply not
	// installed is an absence and never a failure — there is nothing for a
	// caller to do about it and nothing to report.
	Detect(project fs.FS) bool

	// Root returns the harness's own directory for one scope, relative to that
	// scope's root: the project root at `project` scope, and the user's home
	// directory at `user` scope. The second result is false where the harness
	// has no unambiguous location for that scope, which is the whole of the
	// adapter's answer to whether an asset may declare it.
	//
	// It is relative, and joined by the caller, because an adapter that read
	// the environment for a home directory would be a second place in harnaas
	// deciding where a user's files live.
	Root(scope manifest.Scope) (string, bool)

	// Destination returns where one asset installs on this harness, relative to
	// the resolved scope root — the harness's own directory for the asset's
	// scope, which is [Adapter.Root] joined to the project root or to the
	// user's home. A rule resolves to `rules/house-style.md` there, never to a
	// path counted from the project root, so the same mapping serves both
	// scopes and the lockfile can record a destination that means the same
	// thing on another machine.
	//
	// The second result is false where this harness has no surface for the
	// asset's type. That absence is a value rather than an invented path
	// precisely because a guessed destination is indistinguishable from a real
	// one once it is written: the caller reports the pairing as unsupported and
	// installs the asset's other targets.
	//
	// The asset travels whole rather than as the type, id and scope a mapping
	// reads, for the reason a source request does: the fields a diagnostic needs
	// are not the fields the mapping needs, and narrowing the parameter would
	// make every caller's messages worse to keep a signature shorter.
	Destination(asset manifest.Asset) (Destination, bool)
}

// Destination is where one asset installs on one harness, together with the
// terms it installs on.
//
// The terms travel with the path because they are decided by the same lookup:
// which surface a type maps to is what settles how current that surface is and
// what has to happen to the bytes on their way into it. Splitting them would let
// a caller obtain a path and write it without ever asking whether the harness
// still reads there.
type Destination struct {
	// Path is the installed file relative to the resolved scope root,
	// slash-separated. Whether it stays inside that root is not this value's
	// promise: the write goes through a handle anchored there, so an asset id
	// that would escape is refused by the kernel at the moment of the write
	// rather than by a comparison at the moment it was computed.
	Path string

	// Tier is how current the surface is, which decides whether harnaas writes
	// here at all.
	Tier Tier

	// Replacement names the surface that superseded a removed one, and is set
	// only where Tier is [TierRemoved]. It is what makes the refusal actionable:
	// the reader is being told the harness stopped reading this path, and the
	// only useful next sentence is where it reads instead.
	Replacement string

	// Note is the sentence the install report carries for a gated or a legacy
	// surface — the setup the user still has to perform, or the deprecation
	// they should plan for. A live surface carries none, because a note nobody
	// has to act on teaches a reader to skip them all.
	Note string

	// Renderer names the transformation from the source's bytes to the ones
	// that land here. It is a name rather than a function because an adapter
	// declares what a surface needs while the rendering layer owns how it is
	// done: an adapter carrying an implementation would import the layer the
	// import boundary exists to keep out.
	Renderer Renderer
}

// Tier is how current a harness surface is, which decides whether harnaas writes
// to it.
//
// It exists because a harness that has moved on from a path does not say so: the
// write succeeds, the file appears, and nothing ever reads it. That is the exact
// outcome a tool whose purpose is telling a team what is in effect must not
// produce, so the state of a surface is data harnaas carries rather than
// something a user discovers.
type Tier string

const (
	// TierLive is a surface the harness reads today. It is written with no
	// note, which is what keeps the notes on the other tiers worth reading.
	TierLive Tier = "live"

	// TierGated is a surface the harness reads only once the user has enabled
	// something. It is written, with the setup note carried into the install
	// report, because the file is correct and the remaining step is theirs.
	TierGated Tier = "gated"

	// TierLegacy is a surface the harness still reads but has deprecated. It is
	// written, with the deprecation note carried into the report, so a team
	// learns before the surface becomes removed rather than after.
	TierLegacy Tier = "legacy"

	// TierRemoved is a surface the harness no longer reads. Writing there is a
	// guaranteed silent no-op, so it is refused rather than written, naming the
	// surface that replaced it.
	TierRemoved Tier = "removed"
)

// Renderer names the transformation between a source's bytes and the bytes that
// land at a destination.
//
// A name rather than a function keeps the adapter layer and the rendering layer
// apart, and it is also what makes a surface able to declare a renderer nobody
// has written yet: selecting one with no implementation reports the pairing
// unsupported and names the renderer, which is a truthful outcome, where falling
// back to copying the bytes would write a file the harness cannot read.
type Renderer string

const (
	// RendererIdentity reproduces the source bytes exactly, including
	// frontmatter, line endings and trailing whitespace. It is what almost
	// every surface declares, and it is deliberately a renderer rather than the
	// absence of one: copying is the default, not the rule.
	RendererIdentity Renderer = "identity"

	// RendererAsSkill delivers an asset through a harness's skill surface when
	// its own surface is absent — a command as a SKILL.md the model is told not
	// to invoke on its own initiative. It is an emulation, and is reported as
	// one rather than as plain success.
	RendererAsSkill Renderer = "as-skill"
)

package adapter

import (
	"fmt"
	"slices"
	"strings"
	"sync"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// Registry is the set of named adapters this binary can install through, keyed
// by the harness each one addresses.
//
// A registry value rather than one package-level map is what lets a test
// exercise lookup — including the failure for a harness nobody wrote an adapter
// for — without reaching into the set the binary itself ships.
type Registry struct {
	mu sync.Mutex

	// adapters holds each adapter as a value rather than a constructor, which is
	// deliberately unlike the source-kind registry: a kind remembers which
	// archives this run has already fetched and so belongs to the run, while an
	// adapter is a mapping from an asset to a path and has nothing to remember.
	// Handing every run its own copy of a pure mapping would suggest it did.
	adapters map[harness.ID]Adapter
}

// Default is the registry the adapters shipped with this binary register into,
// and the one the install flow resolves destinations through. An adapter package
// registers itself from its own init, so an adapter that has been linked in is an
// adapter that works.
var Default = &Registry{}

// Register adds an adapter to [Default].
func Register(adapter Adapter) {
	Default.Register(adapter)
}

// Register adds an adapter under the harness it addresses.
//
// A second adapter for one harness panics rather than replacing or ignoring the
// first. Registration happens during package initialization, before the process
// has read anything, so the only way to reach it is a mistake in harnaas's own
// wiring — and both silent outcomes are a binary that installs through whichever
// adapter happened to be linked last.
func (r *Registry) Register(adapter Adapter) {
	id := adapter.Harness()

	r.mu.Lock()
	defer r.mu.Unlock()

	if r.adapters == nil {
		r.adapters = make(map[harness.ID]Adapter)
	}
	if _, registered := r.adapters[id]; registered {
		panic(fmt.Sprintf("adapter: harness %q has two adapters registered", id))
	}
	r.adapters[id] = adapter
}

// Lookup returns the adapter for a harness.
//
// A harness with no adapter is not a broken install by itself: skills and
// instructions reach every harness through shared locations, and this lookup only
// happens for the types that have no shared equivalent. That is why the failure
// is a typed diagnostic the caller can attribute to the asset that needed it,
// rather than something the registry decides is fatal.
func (r *Registry) Lookup(id harness.ID) (Adapter, error) {
	r.mu.Lock()
	defer r.mu.Unlock()

	adapter, registered := r.adapters[id]
	if !registered {
		return nil, &NotRegisteredError{Harness: id, Registered: r.harnessesLocked()}
	}
	return adapter, nil
}

// Registered reports whether a harness has a named adapter.
//
// It is separate from [Registry.Lookup] because the install flow asks the
// question long before it has an asset to blame for the answer: a harness with no
// adapter still installs every shared asset, and building a diagnostic to throw
// away would be the wrong shape for that path.
func (r *Registry) Registered(id harness.ID) bool {
	r.mu.Lock()
	defer r.mu.Unlock()

	_, registered := r.adapters[id]
	return registered
}

// Harnesses returns every harness with a named adapter, sorted.
//
// Sorted rather than in registration order, because registration order is
// whatever the import graph happens to produce and this list is rendered into the
// message a user reads when their harness is not among them.
func (r *Registry) Harnesses() []harness.ID {
	r.mu.Lock()
	defer r.mu.Unlock()

	return r.harnessesLocked()
}

// Adapters returns every registered adapter, in [Registry.Harnesses] order, so a
// caller that walks them reports the same thing on every run.
func (r *Registry) Adapters() []Adapter {
	r.mu.Lock()
	defer r.mu.Unlock()

	adapters := make([]Adapter, 0, len(r.adapters))
	for _, id := range r.harnessesLocked() {
		adapters = append(adapters, r.adapters[id])
	}
	return adapters
}

// harnessesLocked returns the registered harnesses in sorted order. The caller
// holds the lock.
func (r *Registry) harnessesLocked() []harness.ID {
	ids := make([]harness.ID, 0, len(r.adapters))
	for id := range r.adapters {
		ids = append(ids, id)
	}
	slices.Sort(ids)
	return ids
}

// NotRegisteredError reports a harness this binary has no named adapter for.
//
// The manifest layer has already accepted the name, because the roster
// recognizes more harnesses than there are adapters and that is the intended
// state: a harness harnaas knows about receives every shared asset without one.
// So the problem is never "this harness does not exist" — it is that the asset in
// hand is of a type with no shared equivalent, and the message has to say which
// harnesses could have taken it.
type NotRegisteredError struct {
	// Harness is the harness with no adapter, exactly as the manifest wrote it.
	Harness harness.ID

	// Registered is every harness this binary has an adapter for, sorted.
	Registered []harness.ID
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *NotRegisteredError) Error() string {
	return fmt.Sprintf(
		"harnaas has no adapter for the harness %q, and a %s, %s or %s asset has no shared location to install to\n\n"+
			"%s Skills and instructions need no adapter and install for every harness harnaas recognizes.",
		e.Harness,
		manifest.AssetTypeRule, manifest.AssetTypeCommand, manifest.AssetTypePersona,
		e.remedy(),
	)
}

// remedy names the harnesses that would have worked, or says plainly that there
// are none. An empty registry is unreachable from a built binary — it links at
// least one adapter — but a message reading "target one of: ." is worse than one
// stating the situation.
func (e *NotRegisteredError) remedy() string {
	if len(e.Registered) == 0 {
		return fmt.Sprintf("This harnaas has no adapters at all, so remove the entry from %s.", manifest.FileName)
	}

	names := make([]string, 0, len(e.Registered))
	for _, id := range e.Registered {
		names = append(names, fmt.Sprintf("%q", id))
	}

	return fmt.Sprintf(
		"Change the entry's %q in %s to a harness harnaas has an adapter for: %s.",
		"targets", manifest.FileName, strings.Join(names, ", "),
	)
}

package adapter

import (
	"fmt"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// ResolveRoot returns the harness directory an asset installs beneath: the
// adapter's own root for the asset's scope, relative to that scope's own root —
// the project root at `project` scope, the user's home at `user` scope.
//
// Which scope an asset has is settled long before this: [manifest.Interpret]
// defaults an undeclared one to `project`, refuses a scope harnaas does not
// define, and refuses `user` where the *roster* records no per-user location.
// What is left for this layer is the question only an adapter can answer — does
// this harness have an unambiguous location for that scope — and the roster's
// answer is deliberately not taken as this one. The roster is a fact about a
// harness the manifest layer can check without linking a single adapter; the
// adapter is the thing that actually knows its own directories, and where the
// two disagree the adapter is right.
//
// A refusal is a refusal, never a quieter install: an asset that asked for
// `user` scope and was given the project root would be installed somewhere its
// author did not ask for, in a file they would have no reason to look at.
func ResolveRoot(a Adapter, asset manifest.Asset) (string, error) {
	scope := asset.Scope
	if scope == "" {
		// An Asset always carries a scope, because Interpret is the only route
		// to one and it defaults an undeclared field. The restatement is not a
		// second place the default is decided — it is what stops a zero value
		// reaching a.Root("") and producing a diagnostic about a scope nobody
		// wrote.
		scope = manifest.ScopeProject
	}

	root, offered := a.Root(scope)
	if !offered {
		return "", &UnsupportedScopeError{
			AssetID: asset.ID,
			Type:    asset.Type,
			Harness: a.Harness(),
			Scope:   scope,
		}
	}

	return root, nil
}

// UnsupportedScopeError reports an asset whose scope this harness has no
// unambiguous directory for.
//
// It names the asset and the harness because the pairing is what is wrong:
// `user` scope is correct for the asset and the harness is correct for the
// project, and only together do they name a location harnaas would have to
// invent. Inventing one is the outcome this refusal exists to prevent — an
// asset installed under a guessed per-user directory reports success, is never
// read, and leaves the team believing it is in effect.
type UnsupportedScopeError struct {
	// AssetID is the asset that asked for the scope.
	AssetID string

	// Type is the asset's type, which is how the message names it in the
	// author's own vocabulary rather than as "the asset".
	Type manifest.AssetType

	// Harness is the harness with no directory for that scope.
	Harness harness.ID

	// Scope is the scope that could not be resolved.
	Scope manifest.Scope
}

// Error states the problem and then the fix, as every user-facing diagnostic
// does.
func (e *UnsupportedScopeError) Error() string {
	return fmt.Sprintf(
		"the %s %q installs at %q scope, and the harness %q has no unambiguous location for that scope\n\n"+
			"%s",
		e.Type, e.AssetID, e.Scope, e.Harness,
		e.remedy(),
	)
}

// remedy names the edit that fixes it, which depends on which scope was asked
// for. Dropping the scope is an edit only where there is a scope to drop: at
// `project` scope there is nothing to remove and the entry's only route to a
// harness that can take it is its `targets`.
func (e *UnsupportedScopeError) remedy() string {
	if e.Scope == manifest.ScopeUser {
		return fmt.Sprintf(
			"Remove %q from the entry in %s so it installs at %q scope, or narrow the entry's %q to harnesses with a per-user location.",
			"scope", manifest.FileName, manifest.ScopeProject, "targets",
		)
	}

	return fmt.Sprintf(
		"Remove %q from the entry's %q in %s.",
		e.Harness, "targets", manifest.FileName,
	)
}

package adapter_test

import (
	"io/fs"
	"path"
	"testing"
	"testing/fstest"

	"github.com/stretchr/testify/assert"

	"github.com/harnaas/harnaas/cmd/harnaas/cli/adapter"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/harness"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/manifest"
)

// testAdapter is an adapter shaped like the ones harnaas will ship: a directory
// per scope, a surface for some types and none for others.
//
// The contract is what these tests are about, so the surfaces are declared as
// data rather than mapped by a method — an adapter that computed them would be
// asserting its own arithmetic instead of the shape every adapter has to present.
type testAdapter struct {
	id harness.ID

	// roots is the harness's directory per scope. A scope absent from the map is
	// one this adapter does not offer.
	roots map[manifest.Scope]string

	// surfaces is the destination for each asset type this harness has one for,
	// relative to the scope root, with `{id}` standing in for the asset id.
	surfaces map[manifest.AssetType]adapter.Destination

	// evidence is the path whose presence means the harness is in use.
	evidence string
}

var _ adapter.Adapter = (*testAdapter)(nil)

func (a *testAdapter) Harness() harness.ID { return a.id }

func (a *testAdapter) Detect(project fs.FS) bool {
	_, err := fs.Stat(project, a.evidence)
	return err == nil
}

func (a *testAdapter) Root(scope manifest.Scope) (string, bool) {
	root, offered := a.roots[scope]
	return root, offered
}

func (a *testAdapter) Destination(asset manifest.Asset) (adapter.Destination, bool) {
	surface, supported := a.surfaces[asset.Type]
	if !supported {
		return adapter.Destination{}, false
	}
	if _, offered := a.roots[asset.Scope]; !offered {
		return adapter.Destination{}, false
	}

	surface.Path = path.Join(surface.Path, asset.ID+".md")
	return surface, true
}

// claudeLike is the adapter these tests exercise the contract through: two
// scopes, a live rules surface, and no surface at all for a persona.
func claudeLike() *testAdapter {
	return &testAdapter{
		id: harness.ClaudeCode,
		roots: map[manifest.Scope]string{
			manifest.ScopeProject: ".claude",
			manifest.ScopeUser:    ".claude",
		},
		surfaces: map[manifest.AssetType]adapter.Destination{
			manifest.AssetTypeRule: {Path: "rules", Tier: adapter.TierLive, Renderer: adapter.RendererIdentity},
		},
		evidence: ".claude",
	}
}

func asset(assetType manifest.AssetType, id string, scope manifest.Scope) manifest.Asset {
	return manifest.Asset{Type: assetType, ID: id, Targets: []harness.ID{harness.ClaudeCode}, Scope: scope}
}

// TestDestinationIsRelativeToTheResolvedScopeRoot pins the one thing every
// caller of the contract depends on: the same mapping serves both scopes, so the
// path the lockfile records means the same thing on another machine.
func TestDestinationIsRelativeToTheResolvedScopeRoot(t *testing.T) {
	t.Parallel()

	a := claudeLike()

	project, found := a.Destination(asset(manifest.AssetTypeRule, "house-style", manifest.ScopeProject))
	assert.True(t, found)
	assert.Equal(t, "rules/house-style.md", project.Path)

	user, found := a.Destination(asset(manifest.AssetTypeRule, "house-style", manifest.ScopeUser))
	assert.True(t, found)
	assert.Equal(t, project.Path, user.Path, "the scope moves the root, not the destination beneath it")
}

// TestNoSurfaceForATypeIsReportedRatherThanInvented is task 5.2's whole point.
// A guessed path is indistinguishable from a real one once it has been written,
// so the absence has to be a value the caller cannot mistake for a destination.
func TestNoSurfaceForATypeIsReportedRatherThanInvented(t *testing.T) {
	t.Parallel()

	destination, found := claudeLike().Destination(asset(manifest.AssetTypePersona, "reviewer", manifest.ScopeProject))

	assert.False(t, found)
	assert.Equal(t, adapter.Destination{}, destination, "nothing a caller could write is handed back")
}

// TestAScopeTheAdapterDoesNotOfferHasNoRootAndNoDestination is the shape scope
// validation reads: an adapter states the scopes it has an unambiguous location
// for, and states it in one place.
func TestAScopeTheAdapterDoesNotOfferHasNoRootAndNoDestination(t *testing.T) {
	t.Parallel()

	projectOnly := claudeLike()
	delete(projectOnly.roots, manifest.ScopeUser)

	root, offered := projectOnly.Root(manifest.ScopeUser)
	assert.False(t, offered)
	assert.Empty(t, root)

	destination, found := projectOnly.Destination(asset(manifest.AssetTypeRule, "house-style", manifest.ScopeUser))
	assert.False(t, found)
	assert.Equal(t, adapter.Destination{}, destination)
}

func TestRootIsRelativeToTheScopesOwnRoot(t *testing.T) {
	t.Parallel()

	for _, scope := range []manifest.Scope{manifest.ScopeProject, manifest.ScopeUser} {
		root, offered := claudeLike().Root(scope)

		assert.True(t, offered)
		assert.Equal(t, ".claude", root)
		assert.False(t, path.IsAbs(root), "an adapter never decides where a user's files live")
	}
}

// TestDetectionReadsAndCreatesNothing is carried by the signature rather than by
// this test — an fs.FS has no way to write — so what is asserted here is the
// other half: a harness that is simply not installed is an absence, never a
// failure a caller has to handle.
func TestDetectionReadsAndCreatesNothing(t *testing.T) {
	t.Parallel()

	using := fstest.MapFS{".claude/settings.json": &fstest.MapFile{}}
	assert.True(t, claudeLike().Detect(using))

	empty := fstest.MapFS{"README.md": &fstest.MapFile{}}
	assert.False(t, claudeLike().Detect(empty))
}

// TestASurfaceCarriesItsTermsWithItsPath is why [adapter.Destination] is one
// value: a caller cannot obtain a path and write it without having been told
// whether the harness still reads there and what has to happen to the bytes.
func TestASurfaceCarriesItsTermsWithItsPath(t *testing.T) {
	t.Parallel()

	removed := claudeLike()
	removed.surfaces[manifest.AssetTypeCommand] = adapter.Destination{
		Path:        "commands",
		Tier:        adapter.TierRemoved,
		Replacement: ".claude/skills",
	}

	destination, found := removed.Destination(asset(manifest.AssetTypeCommand, "review", manifest.ScopeProject))

	assert.True(t, found)
	assert.Equal(t, "commands/review.md", destination.Path)
	assert.Equal(t, adapter.TierRemoved, destination.Tier)
	assert.Equal(t, ".claude/skills", destination.Replacement)
}

